-- Demo content: reviews, gist, comments, salaries and interviews for the FICTIONAL demo companies.
-- Every row has is_demo = true so the site can label it "Sample". Nothing here refers to a real company or person.
-- Generated by script; each value was checked against the table constraints before this file was written.
-- To remove all of it later:
--   DELETE FROM moderation_queue WHERE entity_id IN (SELECT id FROM reviews WHERE is_demo UNION SELECT id FROM gists WHERE is_demo
--     UNION SELECT id FROM gist_comments WHERE is_demo UNION SELECT id FROM salary_reports WHERE is_demo UNION SELECT id FROM interviews WHERE is_demo);
--   DELETE FROM reviews WHERE is_demo; DELETE FROM gists WHERE is_demo; DELETE FROM salary_reports WHERE is_demo; DELETE FROM interviews WHERE is_demo;
BEGIN;

CREATE TEMP TABLE d_reviews(n int, slug text, employment text, job_title text, department text, location text, tenure int, headline text, body text,
  r1 smallint, r2 smallint, r3 smallint, r4 smallint, r5 smallint, r6 smallint, r7 smallint, rec boolean, again boolean, helpful int, anon int, ago int) ON COMMIT DROP;

                    would_recommend, would_work_again, helpful_count, status, risk, created_at, published_at, is_demo, demo_anon)
SELECT md5('demo-review-' || d.n)::uuid, c.id, d.employment::employment_status, d.job_title, d.department, d.location, d.tenure, d.headline, d.body,
       round((d.r1 + d.r2 + d.r3 + d.r4 + d.r5 + d.r6 + d.r7) / 7.0, 2), d.rec, d.again, d.helpful, 'APPROVED', 'LOW',
       now() - make_interval(days => d.ago), now() - make_interval(days => d.ago), true, d.anon
FROM d_reviews d JOIN companies c ON c.slug = d.slug
ON CONFLICT (id) DO NOTHING;

SELECT md5('demo-review-' || d.n)::uuid, v.dim::rating_dimension, v.score
FROM d_reviews d
CROSS JOIN LATERAL (VALUES ('MANAGEMENT', d.r1), ('COMPENSATION', d.r2), ('CULTURE', d.r3), ('WORK_LIFE_BALANCE', d.r4),
                           ('CAREER_GROWTH', d.r5), ('JOB_SECURITY', d.r6), ('BENEFITS', d.r7)) AS v(dim, score)
WHERE EXISTS (SELECT 1 FROM reviews r WHERE r.id = md5('demo-review-' || d.n)::uuid)
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE d_gists(n int, cat text, slug text, body text, likes int, anon int, hrs int) ON COMMIT DROP;

SELECT md5('demo-gist-' || d.n)::uuid, c.id, d.cat::gist_category, d.body, d.likes, 'APPROVED', 'LOW', t.ts, t.ts, true, d.anon
FROM d_gists d
LEFT JOIN companies c ON c.slug = d.slug
CROSS JOIN LATERAL (SELECT now() - make_interval(hours => d.hrs) AS ts) t
ON CONFLICT (id) DO NOTHING;

CREATE TEMP TABLE d_comments(n int, gist_n int, anon int, body text, hrs int) ON COMMIT DROP;

SELECT md5('demo-comment-' || d.n)::uuid, g.id, d.body, 'APPROVED', 'LOW', t.ts, t.ts, true, d.anon
FROM d_comments d
JOIN gists g ON g.id = md5('demo-gist-' || d.gist_n)::uuid
CROSS JOIN LATERAL (SELECT now() - make_interval(hours => d.hrs) AS ts) t
ON CONFLICT (id) DO NOTHING;

CREATE TEMP TABLE d_salaries(n int, slug text, title text, tslug text, dept text, location text, lvl text, etype text, base int, allow int, bonus int, yr int, ago int) ON COMMIT DROP;

                           base_salary, allowances, bonus, year, status, risk, created_at, published_at, is_demo)
SELECT md5('demo-salary-' || d.n)::uuid, c.id, d.title, d.tslug, d.dept, d.location, d.lvl::experience_level, d.etype::employment_type, 'MONTHLY',
       d.base, d.allow, d.bonus, d.yr, 'APPROVED', 'LOW', now() - make_interval(days => d.ago), now() - make_interval(days => d.ago), true
FROM d_salaries d JOIN companies c ON c.slug = d.slug
ON CONFLICT (id) DO NOTHING;

CREATE TEMP TABLE d_interviews(n int, slug text, role text, rslug text, location text, stage text, diff text, stages int, assess text, outcome text, exp text, month text, helpful int, anon int, ago int) ON COMMIT DROP;

                       experience, interviewed_on, helpful_count, status, risk, created_at, published_at, is_demo, demo_anon)
SELECT md5('demo-interview-' || d.n)::uuid, c.id, d.role, d.rslug, d.location, d.stage, d.diff::difficulty_level, d.stages, d.assess, d.outcome::interview_outcome,
       d.exp, (d.month || '-01')::date, d.helpful, 'APPROVED', 'LOW', now() - make_interval(days => d.ago), now() - make_interval(days => d.ago), true, d.anon
FROM d_interviews d JOIN companies c ON c.slug = d.slug
ON CONFLICT (id) DO NOTHING;

CREATE TEMP TABLE d_questions(n int, int_n int, question text) ON COMMIT DROP;

SELECT md5('demo-question-' || d.n)::uuid, md5('demo-interview-' || d.int_n)::uuid, d.question,
       encode(digest(trim(regexp_replace(lower(d.question), '[^a-z0-9]+', ' ', 'g')), 'sha256'), 'hex')
FROM d_questions d
WHERE EXISTS (SELECT 1 FROM interviews i WHERE i.id = md5('demo-interview-' || d.int_n)::uuid)
ON CONFLICT (id) DO NOTHING;

SELECT 'REVIEW'::entity_type, id, 'APPROVED'::moderation_status, 'LOW'::risk_level, '{}'::text[], true, published_at, published_at FROM reviews WHERE is_demo
ON CONFLICT DO NOTHING;

SELECT 'GIST'::entity_type, id, 'APPROVED'::moderation_status, 'LOW'::risk_level, '{}'::text[], true, published_at, published_at FROM gists WHERE is_demo
ON CONFLICT DO NOTHING;

SELECT 'GIST_COMMENT'::entity_type, id, 'APPROVED'::moderation_status, 'LOW'::risk_level, '{}'::text[], true, published_at, published_at FROM gist_comments WHERE is_demo
ON CONFLICT DO NOTHING;

SELECT 'SALARY_REPORT'::entity_type, id, 'APPROVED'::moderation_status, 'LOW'::risk_level, '{}'::text[], true, published_at, published_at FROM salary_reports WHERE is_demo
ON CONFLICT DO NOTHING;

SELECT 'INTERVIEW'::entity_type, id, 'APPROVED'::moderation_status, 'LOW'::risk_level, '{}'::text[], true, published_at, published_at FROM interviews WHERE is_demo
ON CONFLICT DO NOTHING;

COMMIT;
