INSERT INTO d_reviews VALUES
(1,'abc-logistics','FORMER','Operations Associate','Operations','Lagos',24,'Good people, slow approvals','Good people and decent hands-on training, but approvals are slow and overtime during peak season is often paid late. Ask about shift rules and fuel allowances before you sign.',3,3,4,2,3,3,4,true,false,12,117,9),
(2,'abc-logistics','CURRENT','Fleet Coordinator','Operations','Lagos',18,'Clear targets, depends on the depot','Targets are clear and my supervisor explains the reasoning behind decisions. Pay is about average for the sector. Growth depends heavily on which depot you land in.',4,3,4,3,3,4,3,true,true,31,142,21),
(3,'abc-logistics','FORMER','HR Officer','People','Lagos',36,'Colleagues made it bearable','Policies change without notice and promotion timelines are never written down. Colleagues made it bearable, and the staff transport is genuinely useful.',2,3,3,3,2,3,4,false,false,19,168,47),
(4,'xyz-technologies','CURRENT','Backend Engineer','Engineering','Lagos',30,'Engineers are trusted','Engineers are trusted to make real decisions and code review is taken seriously. Salary reviews happen once a year and are reasonably transparent. Expect occasional late nights before launches.',4,4,5,3,4,4,4,true,true,27,203,6),
(5,'xyz-technologies','FORMER','Product Designer','Product','Lagos',20,'Great learning, unclear promotion path','Great learning environment and a manager who gave honest feedback. I left because the design team stayed small and promotion paths were unclear.',4,3,5,4,3,4,3,true,true,14,221,33),
(6,'xyz-technologies','CURRENT','Customer Success Lead','Operations','Lagos',12,'Hybrid that is real','Hybrid working is real here, not just a slogan. The company communicates openly about targets and the health cover is better than most places I have worked.',5,4,4,5,4,4,5,true,true,22,236,15),
(7,'example-holdings','FORMER','Accountant','Finance','Abuja',48,'Stable, but slow to move','A large and stable employer, but decisions take a long time to travel up and down the hierarchy. Pay rises were rare and benefits looked good on paper but were slow to be delivered.',2,2,3,3,2,4,3,false,false,16,254,52),
(8,'example-holdings','CURRENT','Administrative Officer','Administration','Abuja',24,'Security is the draw','Job security is the main reason people stay. Working hours are predictable, though the culture is formal and you wait your turn for opportunities.',3,3,3,4,2,4,3,true,true,9,271,28),
(9,'example-holdings','FORMER','Procurement Officer','Supply Chain','Abuja',30,'Very bureaucratic','Very bureaucratic. Approvals needed several sign-offs even for small purchases, which got frustrating. You learn process discipline, but speed is not valued.',2,3,2,3,2,3,3,false,false,11,288,64),
(10,'ife-foods','CURRENT','Production Supervisor','Manufacturing','Osogbo',36,'Well-run plant','Safety briefings are taken seriously and the plant is well run. Overtime is paid on time, and the canteen meals are subsidised. Management could communicate changes earlier.',4,3,4,3,4,4,4,true,true,18,302,11),
(11,'ife-foods','FORMER','Sales Representative','Sales','Ibadan',18,'Fair targets, lots of travel','Fair targets and a commission structure that is easy to understand. Lots of travel, so expect long weeks on the road. Good place to start a sales career.',4,4,4,3,4,3,3,true,true,13,315,38),
(12,'ife-foods','CURRENT','Quality Analyst','Quality','Osogbo',14,'Real training budget','Supportive team lead and clear procedures. Pay is modest, but the training budget is real and I have been sponsored for two courses.',4,3,4,4,5,4,3,true,true,10,327,19),
(13,'kora-bank','CURRENT','Relationship Officer','Retail Banking','Lagos',20,'Strong brand, relentless targets','Targets are aggressive and tied to deposit growth, which can feel relentless in the last quarter. The brand opens doors, and the training in the first year is excellent.',3,3,3,2,4,4,4,true,false,34,341,8),
(14,'kora-bank','FORMER','Credit Analyst','Risk','Lagos',28,'Great training, long hours','Strong technical training and a thorough credit process. Hours are long and weekends are not always your own. Pay is competitive until mid-level, then flattens.',3,4,3,2,4,3,4,true,false,21,356,26),
(15,'kora-bank','FORMER','Teller','Operations','Lagos',40,'Stable but heavy pressure','Stable income, but the targets and reconciliation pressure are heavy and recognition is uneven between branches.',2,3,2,2,3,4,3,false,false,15,369,58),
(16,'naija-health-partners','CURRENT','Clinic Manager','Operations','Port Harcourt',26,'Mission-driven, tight resources','Mission-driven team that genuinely cares about patients. Resources can be tight and equipment requests take time, but leadership listens and acts when it can.',4,3,5,3,4,3,3,true,true,12,382,12),
(17,'naija-health-partners','FORMER','Registered Nurse','Clinical','Port Harcourt',22,'Rewarding, demanding shifts','Rewarding work with supportive colleagues, but shift patterns are demanding and staffing is thin on nights. Allowances for night shifts were paid regularly.',3,3,4,2,3,3,4,true,false,17,395,44),
(18,'naija-health-partners','CURRENT','Finance Associate','Finance','Port Harcourt',16,'Small team, big exposure','Small team, so you get exposure to everything quickly. Processes are still being formalised, which is exciting if you like building things and frustrating if you do not.',4,3,4,4,5,3,3,true,true,8,111,22);
INSERT INTO reviews(id, company_id, employment, job_title, department, location, tenure_months, headline, body, overall_rating,
INSERT INTO review_ratings(review_id, dimension, score)
INSERT INTO d_gists VALUES
(1,'CAREER_ADVICE','abc-logistics','Things I wish someone told me before joining a logistics company: ask about shift pay, fuel allowances and who is responsible for vehicle damage.',48,207,2),
(2,'SALARY',NULL,'Got an offer with a "competitive package". Always ask for the breakdown: base, housing and transport are three different conversations.',96,112,5),
(3,'WORK_LIFE',NULL,'Month-end reconciliation season. Please log off. The spreadsheet will still be there tomorrow.',152,318,26),
(4,'INTERVIEW','kora-bank','Panel of four. One asked for my five-year plan, another asked how I would handle a missing invoice. Prepare for both kinds of question.',23,154,50),
(5,'MANAGEMENT',NULL,'A good manager is someone who tells you the bad news early. If your boss only calls you in after problems blow up, that is a signal.',67,241,76),
(6,'PROMOTION','example-holdings','Asked about the promotion timeline in my interview and got a vague answer. Two years later I understood why. Always ask how many people were promoted last year.',41,189,100),
(7,'REMOTE_WORK','xyz-technologies','Hybrid that actually works: two fixed office days, meetings clustered on those days, and nobody judged on camera presence. Rare, so ask how it works in practice.',58,276,124),
(8,'FUNNY',NULL,'The meeting that could have been an email now has a follow-up meeting to discuss the email.',204,133,148),
(9,'OFFICE_POLITICS',NULL,'Be kind to the receptionist, the drivers and the cleaners. They know everything about the company and they remember how you treated them.',122,298,196),
(10,'TOXIC_WORKPLACE',NULL,'If people apologise on behalf of the company while onboarding you, that is not culture, that is a warning label.',88,165,244),
(11,'CAREER_ADVICE',NULL,'First job tip: keep a weekly note of what you delivered. When review season comes you will not be trying to remember what you did in March.',134,223,292),
(12,'SALARY','ife-foods','Negotiated my start salary for the first time. They said yes to a higher base but no to a signing bonus. Asking cost me nothing.',37,176,340);
INSERT INTO gists(id, company_id, category, body, like_count, status, risk, created_at, published_at, is_demo, demo_anon)
INSERT INTO d_comments VALUES
(1,1,189,'Fuel allowance especially. Mine was verbal only until I asked for it in writing.',1),
(2,1,266,'Also ask whether overtime is paid or "compensated with time off".',1),
(3,2,301,'Splitting housing and transport into separate lines made my offer look much bigger than it really was.',3),
(4,3,122,'Needed to read this today.',20),
(5,5,175,'Learned this the hard way.',60),
(6,9,233,'100 percent. The driver knew about the restructuring months before it was announced.',150),
(7,11,144,'Doing this since January and it made my review so much easier.',250);
