INSERT INTO d_interviews VALUES
(1,'xyz-technologies','Backend Engineer','backend-engineer','Lagos','Final interview','HARD',4,'TAKE_HOME','OFFER','Recruiter screen, then a take-home API task, a system design round and a final conversation with the engineering lead. They care about how you explain trade-offs, not just the final answer.','2026-08',19,145,40),
(2,'xyz-technologies','Product Designer','product-designer','Lagos','Portfolio review','MEDIUM',3,'PRESENTATION','REJECTED','Portfolio walkthrough with two designers, then a short design exercise. Feedback was prompt and specific, which I appreciated even though I did not get the role.','2026-07',9,150,55),
(3,'kora-bank','Credit Analyst','credit-analyst','Lagos','Panel interview','MEDIUM',3,'APTITUDE_TEST','OFFER','Aptitude test, then a panel of four, then HR. Expect questions on loan risk, Excel and how you handle pressure at month end.','2026-09',14,160,20),
(4,'abc-logistics','Operations Associate','operations-associate','Lagos','Second interview','EASY',2,'NONE','OFFER','Short phone screen and one in-person chat with the operations manager. Feedback came within a week, and they were upfront about shift patterns.','2026-09',7,172,30),
(5,'ife-foods','Sales Representative','sales-representative','Ibadan','Panel interview','MEDIUM',3,'GROUP_EXERCISE','OFFER','Group exercise, then a panel. They want to see how you pitch under pressure and whether you are comfortable travelling for work.','2026-08',6,181,45);
INSERT INTO interviews(id, company_id, role, role_slug, location, stage_reached, difficulty, stages_count, assessment_type, outcome,
